after.content:
if (failed) {
  const page = context.pages()[0]
  if (page) await page.screenshot({ path: testInfo.outputPath("test-failed-1.png"), fullPage: true })
  if (process.env.JI_REAL_HOST_DISABLE_TRACE !== "1") {
    await context.tracing.stop({ path: testInfo.outputPath("trace.zip") })
  }
} else if (process.env.JI_REAL_HOST_DISABLE_TRACE !== "1") {
  await context.tracing.stop()
}
await context.close()
